// change the value of TARGET_ACCOUNT to the X username you want to scrap
const message = "Yah... Tampaknya server i-booster lagi error nih, bisa coba lagi nanti ya... 😓 (Berdoa juga agar Telkom ngasih server yg lebih layak dari ini 🙏)";
return [{ json: { message } }];

const root = $input.item.json;

let command = null;
let args = [];
let rawText = "";
let chat_id = null;
let from_id = null;
let from_username = null;
let from_name = null;
let inet = null;
let isCommand = false;
let fromCallback = false;

// === 1. EVENT DARI TOMBOL (INLINE BUTTON) ===
if (root.callback_query) {
  const cb = root.callback_query;
  const data = cb.data || "";          // misal: "retest:172418621229"

  fromCallback = true;

  chat_id = cb.message?.chat?.id || null;
  from_id = cb.from?.id || null;
  from_username = cb.from?.username || null;
  from_name = [
    cb.from?.first_name || "",
    cb.from?.last_name  || "",
  ].join(" ").trim() || null;

  if (data.startsWith("retest:")) {
    inet = data.split(":")[1] || "";

    // kita anggap ini perintah "ukur lagi nomor yg sama"
    isCommand = true;
    command = "ukur";   // seolah user kirim /ukur <INET>
    args = [inet];
  }
}

// === 2. EVENT PESAN BIASA ===
else {
  const msg =
    root.message ??
    root.edited_message ??
    root.channel_post ??
    {};

  rawText = (msg.text ?? msg.caption ?? "").trim();

  chat_id = msg.chat?.id ?? null;
  from_id = msg.from?.id ?? null;
  from_username = msg.from?.username ?? null;
  from_name = [
    msg.from?.first_name ?? "",
    msg.from?.last_name  ?? "",
  ].join(" ").trim() || null;

  if (rawText.startsWith("/")) {
    const parts = rawText.split(/\s+/);
    const first = parts[0];

    command = first.slice(1).split("@")[0];
    args = parts.slice(1);
    isCommand = true;
  }
}

return {
  json: {
    isCommand,
    command,
    args,
    rawText,
    chat_id,
    from_id,
    from_username,
    from_name,
    inet,          // INET dari tombol (kalau ada)
    fromCallback,  // penanda bahwa ini event dari tombol
  },
};

const input = $input.item.json;

const chatId = String(input.chat_id);
const text = (input.rawText || "").trim();
const isCommand = !!input.isCommand;
const command = input.command || null;
const args = input.args || [];

// Static data global
const wfData = $getWorkflowStaticData("global");
if (!wfData.chatStates) wfData.chatStates = {};
const chatState = wfData.chatStates[chatId] || { mode: null, lastQuery: null, lastType: null };

// === REGEX ===

// SN: uppercase alfanumerik, panjang 10-12 (contoh kamu 10-12)
// Kalau kamu mau lebih longgar, ganti {10,12} jadi {8,16}
const snRegex = /^[A-Z0-9]{10,12}$/;

// Helper normalisasi input jadi kandidat INET / SN
function parseCandidate(str) {
  const s = String(str || "").trim();

  // ✅ INET: cari 12 digit SEBAGAI SEKUENS (bukan gabung semua digit)
  // contoh: "INET: 172418621229", "no inet 172418621229 (cek)", forward panjang, dll
  const mInet = s.match(/(^|[^\d])(\b172\d{9}\b)([^\d]|$)/);
if (mInet?.[2]) {
  return { type: "inet", value: mInet[2] };
}


  // ✅ SN: cari token alfanumerik 8–16 (ambil yang paling “niat”)
  // - uppercasing biar kuat kalau forward lowercase
  // - ambil match pertama yang valid
  const upper = s.toUpperCase();
// token 10–16 char alnum, dan wajib ada huruf (biar angka doang gak dianggap SN)
const mSn = upper.match(/\b(?=[A-Z0-9]{10,16}\b)(?=.*[A-Z])[A-Z0-9]+\b/);
if (mSn?.[0]) {
  return { type: "sn", value: mSn[0] };
}


  return null;
}


let mode = "reply";
let message = "";
let inet = null;      // tetap ada supaya workflow kamu yang lama gak pecah
let sn = null;        // SN terpisah
let q = null;         // query umum (inet/sn)
let qType = null;     // "inet" / "sn"

const fromCallback = input.fromCallback || false;

// 🟢 KASUS TOMBOL "ULANGI UKUR"
// (Saat ini kamu masih kirim input.inet dari callback. Kita dukung dua-duanya:
// - kalau input.inet ada -> pakai itu
// - kalau nanti kamu ubah callback jadi input.q -> tetap jalan)
if (fromCallback) {
  // Ambil kandidat dari mana pun yang tersedia (paling sering args[0])
  const cbValue =
    input.q ??
    input.inet ??
    input.sn ??
    (Array.isArray(input.args) ? input.args[0] : null) ??
    input.rawText ??
    "";

  const parsed = parseCandidate(cbValue);

  if (parsed) {
    qType = parsed.type;
    q = parsed.value;

    if (qType === "inet") inet = q;
    if (qType === "sn") sn = q;

    chatState.lastQuery = q;
    chatState.lastType = qType;

    message = "Tunggu yaa...";
    mode = "ukur";

    wfData.chatStates[chatId] = chatState;

    return {
      json: {
        ...input,
        mode,
        message,
        inet,
        sn,
        q,
        qType,
        chatStateMode: chatState.mode,
      },
    };
  }

  // Kalau callback tapi datanya aneh/kosong, jangan jatuh ke await_id (biar gak "Input tidak valid")
  message = "Data tombol tidak terbaca. Coba ketik ulang INET/SN atau tekan /ukur lagi.";
  mode = "reply";

  wfData.chatStates[chatId] = chatState;

  return {
    json: {
      ...input,
      mode,
      message,
      inet: null,
      sn: null,
      q: null,
      qType: null,
      chatStateMode: chatState.mode,
    },
  };
}


// ============ 1) PESAN COMMAND ============
if (isCommand) {
  // Kalau command BUKAN /ukur → keluar dari mode ukur
  if (command !== "ukur") {
    chatState.mode = null;
  }

  if (command === "help") {
    message =
`Cara pakai bot ini:
/help  — Lihat panduan
/about — Info bot
/ukur  — Masuk mode ukur

Setelah /ukur, kamu bisa kirim:
- Nomor INET (12 digit), atau
- SN ONT (contoh: ZTEGC8378EBB / HWTC6B25FEB5)
berkali-kali tanpa ngetik /ukur lagi.`;
    mode = "reply";
  }

  else if (command === "about") {
    message =
`Ini bot buat bantu teknisi cek hasil i-booster <b>TANPA RIBET</b> langsung dari Telegram.

Perintah utama:
/ukur — ukur pakai INET atau SN.`;
    mode = "reply";
  }

  else if (command === "start") {
    message =
`Selamat datang di bot Ibooster Reborn! 

Lemot, tidak ramah pengguna, tidak intuitif, boros baterai, selalu bikin emosi... pokoknya <b>MENYEBALKAN!</b> Itulah LENSA. 😾
Bot ini lahir sebagai bentuk perlawanan dan membuat hidup teknisi jauh lebih mudah, tanpa drama dan tanpa nunggu loading muter-muter cuma buat dapat pesan error. ✊🏻

Ketik /help untuk panduan, atau /ukur untuk mulai ukur.`;
    mode = "reply";
  }

  else if (command === "ukur") {
    const candidate = args[0] || null;

    // Masuk mode ukur
    chatState.mode = "await_id";

    if (!candidate) {
      message =
`Masuk mode ukur.

Silakan kirim salah satu:
- Nomor INET (12 digit), atau
- SN ONT (contoh: ZTEGC8378EBB)

Contoh INET:
172418621229

Contoh SN:
ZTEGC8378EBB`;
      mode = "reply";
    } else {
      const parsed = parseCandidate(candidate);

      if (!parsed) {
        message =
`Input tidak valid.

Kirim salah satu:
- INET 12 digit (contoh: /ukur 172418621229)
- SN ONT (contoh: /ukur ZTEGC8378EBB)

Atau setelah /ukur tanpa parameter, kirim INET/SN langsung.`;
        mode = "reply";
      } else {
        qType = parsed.type;
        q = parsed.value;

        if (qType === "inet") inet = q;
        if (qType === "sn") sn = q;

        chatState.lastQuery = q;
        chatState.lastType = qType;

        message = "Tunggu yaa...";
        mode = "ukur";
      }
    }
  }

  else {
    message =
`Aku cuma kenal command:
/start, /help, /about, /ukur`;
    mode = "reply";
  }
}

// ============ 2) BUKAN COMMAND ============
else {
  if (chatState.mode === "await_id") {
    const parsed = parseCandidate(text);

    if (!parsed) {
      message = "Input tidak valid";
      mode = "reply";
    } else {
      qType = parsed.type;
      q = parsed.value;
      message = "Tunggu yaa...";
      mode = "ukur";
    }

  } else {
    // AUTO-DETECT
    const parsedAuto = parseCandidate(text);

    if (parsedAuto) {
      qType = parsedAuto.type;
      q = parsedAuto.value;
      message = "Tunggu yaa...";
      mode = "ukur";
    } else {
      message = "Ketik /ukur dulu";
      mode = "reply";
    }
  }
}



// Simpan state
wfData.chatStates[chatId] = chatState;

// Return item
return {
  json: {
    ...input,
    mode,
    message,
    inet,
    sn,
    q,
    qType,
    chatStateMode: chatState.mode,
  },
};

// ===== Helper: escape HTML Telegram =====
function esc(str) {
  return String(str ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

const d = $input.item.json.data ?? [];

function raw(i) {
  return d?.[i]?.value ?? "";
}
function val(i) {
  return esc(raw(i));
}

// ===== Emoji mapping =====
const OK = "✅";
const WARN = "⚠️";
const BAD = "❌";
const UNKNOWN = "❔";

// ===== ONU STATUS =====
function onuStatusEmoji(s) {
  const t = String(s ?? "").toUpperCase();
  if (t.includes("ONLINE")) return OK;
  if (t.includes("LOS")) return BAD;
  if (t.includes("DYING GASP")) return UNKNOWN;
  return WARN;
}

// ===== RX HANDLING =====
function stripUnit(v) {
  return String(v ?? "").replace(/dBm/gi, "").trim();
}

function rxEmoji(v) {
  const n = parseFloat(stripUnit(v));
  if (Number.isNaN(n)) return BAD;

  // nilai ekstrem = LOS / data rusak
  if (n < -60 || n > 0) return BAD;

  if (n < -23.99) return WARN;
  return OK;
}

function rxText(v) {
  return esc(stripUnit(v));
}

// ===== ACS STATUS =====
function acsEmoji(v) {
  return String(v ?? "").toLowerCase() === "online" ? OK : WARN;
}

// ===== DATA =====
const msg = esc($input.item.json.message ?? "");
const kes = esc($input.item.json.kesimpulan ?? "");

const onuStatusRaw = raw(9);
const onuRxRaw = raw(19);
const oltRxRaw = raw(22);
const acsRaw = raw(32);

// ===== RESULT EMOJI =====
function resultEmoji() {
  const m = String($input.item.json.message ?? "");
  const k = String($input.item.json.kesimpulan ?? "");

  if (/Hasil pengukuran\s*BAIK/i.test(k)) return OK;
  if (/Status ONT\s*LOS/i.test(m)) return BAD;
  if (/dibawah standar/i.test(m) || /-25/i.test(m)) return WARN;

  if (rxEmoji(onuRxRaw) === BAD || rxEmoji(oltRxRaw) === BAD) return BAD;
  if (rxEmoji(onuRxRaw) === WARN || rxEmoji(oltRxRaw) === WARN) return WARN;

  return OK;
}

// ===== BUILD MESSAGE =====
const message =
`${msg}
<b>${kes}</b> ${resultEmoji()}

<b>ONU status:</b> ${esc(onuStatusRaw)} ${onuStatusEmoji(onuStatusRaw)}
<b>ONU rx:</b> ${rxText(onuRxRaw)} dBm ${rxEmoji(onuRxRaw)}
<b>OLT rx:</b> ${rxText(oltRxRaw)} dBm ${rxEmoji(oltRxRaw)}
<b>SN ONT:</b> <code>${val(8)}</code> (${val(7)})
<b>Conn status (ACS):</b> ${esc(acsRaw)} ${acsEmoji(acsRaw)}
<b>PCRF (Paket):</b> ${val(34)}
<b>GPON:</b> ${val(0)}
`;

return {
  json: {
    message
  }
};

// change the value of TARGET_ACCOUNT to the X username you want to scrap
const message = $input.first().json.message;

return [{ json: { message } }];
